async (page) => {
  // Get accessibility tree snapshot
  const snapshot = await page.accessibility.snapshot();

  // Get DOM structure for key elements
  const formElements = await page.evaluate(() => {
    const elements = [];

    // Get all form inputs, buttons, and headings
    document.querySelectorAll('input, button, h1, h2, h3, [role="region"], [role="group"], label, a').forEach(el => {
      elements.push({
        tag: el.tagName,
        type: el.type || undefined,
        role: el.getAttribute('role'),
        ariaLabel: el.getAttribute('aria-label'),
        ariaLabelledBy: el.getAttribute('aria-labelledby'),
        ariaDescribedBy: el.getAttribute('aria-describedby'),
        id: el.id,
        name: el.name,
        placeholder: el.placeholder,
        textContent: el.textContent?.substring(0, 100),
        class: el.className,
        selector: el.tagName + (el.id ? '#' + el.id : '') + (el.name ? '[name="' + el.name + '"]' : '')
      });
    });

    return elements;
  });

  return {
    snapshot,
    formElements,
    pageTitle: await page.title(),
    url: page.url()
  };
}

